import json,re
p="/Users/ellishewes/.claude/projects/-Users-ellishewes-conductor-workspaces-durhack-proj-yokohama/829c4789-d388-4f09-ab14-3b824c7938d2.jsonl"
hits=[]
with open(p) as f:
    for line in f:
        try: o=json.loads(line)
        except: continue
        if o.get("type")!="assistant": continue
        c=o.get("message",{}).get("content")
        if not isinstance(c,list): continue
        for x in c:
            if isinstance(x,dict) and x.get("type")=="text":
                t=x["text"]
                if re.search(r"(?i)apple watch|watchos|watch app|wearable",t):
                    hits.append((o.get("timestamp"),t[:1500]))
print(len(hits))
for t,x in hits[-8:]:
    print("----",t); print(x)
EOF

