  return ["case", ["==", ["get", "id"], selectedId ?? ""], selected, idle];
}

function selectedColor(selectedId: string | null): unknown[] {
  return ["case", ["==", ["get", "id"], selectedId ?? ""], ACCENT, INK];
}

