sub('''const STAGE_BY_VALUE: Record<number, SleepStage> = {
  [SLEEP_VALUE.inBed]: "inBed",
  // Asleep with no stage (watchOS 8 and older, some apps). Core is the closest stage Kip has.
  [SLEEP_VALUE.asleepUnspecified]: "core",
  [SLEEP_VALUE.awake]: "awake",''', '''// `asleepUnspecified` (watchOS 8 and older, some apps) has no stage in NightUpload, so it is left
