import { StyleSheet, View } from "react-native";
import { radius, space, Text, useColors } from "@/lib/ui";
import { CLUSTER_NOTE, SHADE_KEY_TITLE, UNSHADED_NOTE } from "../copy";
import { SHADE_BANDS, UNSHADED_COLOR } from "../sensors";

function Swatch({ color }: { color: string }) {
  const colors = useColors();
  return <View style={[styles.swatch, { backgroundColor: color, borderColor: colors.border }]} />;
}

function Entry({ color, label }: { color: string; label: string }) {
  return (
    <View style={styles.entry}>
      <Swatch color={color} />
      <Text variant="caption">{label}</Text>
    </View>
  );
}

/** The shade key, what unshaded means, and what clusters do not mean. */
export function SensorLegend() {
  return (
    <View style={styles.root}>
      <Text variant="caption">{SHADE_KEY_TITLE}</Text>
      <View style={styles.row}>
        {SHADE_BANDS.map((band) => (
          <Entry key={band.min} color={band.color} label={band.label} />
        ))}
      </View>
      <Entry color={UNSHADED_COLOR} label="Not shaded" />
      <Text variant="caption">{UNSHADED_NOTE}</Text>
      <Text variant="caption">{CLUSTER_NOTE}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { gap: space.xs },
  row: { flexDirection: "row", flexWrap: "wrap", columnGap: space.md, rowGap: space.xs },
  entry: { flexDirection: "row", alignItems: "center", gap: space.xs },
  swatch: { width: 14, height: 14, borderRadius: radius.sm, borderWidth: 1 },
});
import { SAY_SIMULATED } from "@kip/shared/domain";

export const TITLE = "Kip Map";
/** The label every selected sensor carries (`docs/DOMAIN.md`: Wording rules). */
export const ESTIMATE_LABEL = "indicative road-traffic estimate, WHO curve";
export const SHADE_KEY_TITLE = "Highly sleep disturbed, indicative";
export const CLUSTER_NOTE =
  "Numbered circles count sensors in that spot. They are not an average and do not cover an area. Zoom in to see each sensor.";
export const UNSHADED_NOTE =
  "Not shaded: fewer than 30 nights, no readings, or a latest reading over 3 days old. Select a sensor to see which.";
export const LIST_TITLE = "Sensors";
export const LOADING = "Loading sensors.";
export const SAMPLE_LABEL = `Sample sensors, ${SAY_SIMULATED} data. The city service is not reachable.`;
export const CLAMP_NOTE =
  "Lnight is outside the WHO curve's 40 to 65 dB range, so the estimate uses the nearest end of the range.";
export const NO_SELECTION = "Select a sensor on the map or in the list to see its details.";
export const SOURCE = "Newcastle Urban Observatory";

export const STATE_NOTE = {
  shaded: "",
  outOfRange: CLAMP_NOTE,
  fewNights: "Fewer than 30 nights of data, so this sensor is not shaded.",
  missing: "No readings yet, so this sensor is not shaded.",
  stale: "The latest reading is more than 3 days old, so this sensor is not shaded.",
} as const;

export const STATE_LABEL = {
  shaded: "Shaded",
  outOfRange: "Shaded, clamped",
  fewNights: "Under 30 nights",
  missing: "No readings",
  stale: "Out of date",
} as const;
export { SensorLegend } from "./SensorLegend";
export { SensorList } from "./SensorList";
export { SensorMap, type SensorMapProps } from "./SensorMap";
import type { CitySensors } from "@kip/shared/city";
import { useQuery } from "@tanstack/react-query";
import { useTRPC } from "@/lib/trpc";
import { fixtureSensors } from "../data/fixture";

export type SensorsState =
  | { kind: "loading" }
  | { kind: "sensors"; sensors: CitySensors; simulated: boolean };

/** Server sensors, or the shared fixture labelled simulated when the API cannot be reached. */
export function useCitySensors(): SensorsState {
  const trpc = useTRPC();
  const query = useQuery({ ...trpc.city.sensors.queryOptions(), retry: 1 });
  if (query.data) return { kind: "sensors", sensors: query.data as CitySensors, simulated: false };
  if (query.isPending) return { kind: "loading" };
  return { kind: "sensors", sensors: fixtureSensors, simulated: true };
}
export { SensorMap, type SensorMapProps } from "./components";
export { CityScreen } from "./screens/CityScreen";
export { sensorFeatures } from "./sensors";
// Zod schemas and types for the `city` feature's tRPC inputs and outputs.
export * from "./sensors";
