  lat: number;
  lon: number;
  /** Homes fall anywhere within this many metres of the centre */
  radiusM: number;
  /** Simulated people living here */
  people: number;
  /** 0 to 1: how much nightlife and traffic the area has, for louder nights and more spikes */
  lively: number;
};

/**
