        now: new Date(),
      });
      console.log(
        `simulated: replaced ${tally.replaced} nights with ${tally.nights} nights for ` +
          `${tally.users} people in ${NEWCASTLE_AREAS.length} areas, ${tally.noiseRows} noise rows`,
      );
