  return coverage.cells.some((cell) => cell.simulatedPeople > 0);
}

/** What the heat means, how rough it is, and whether simulated people are in it. */
export function coverageNotes(coverage: CityCoverage, showSimulated = true): string[] {
  const notes = [
    `Shading shows where Kip phones and Apple Watches sensed in the last ${coverage.days} nights, in areas about ${coverage.cellMeters} m across.`,
    `Real nights show only where ${coverage.minPeople} or more people sensed, and never where anyone was.`,
  ];
  if (!hasSimulated(coverage)) return notes;
  if (showSimulated) {
    notes.push(`Includes ${SAY_SIMULATED} people, not real users.`);
  } else {
    const real = coverage.cells.some((cell) => cell.people > 0);
    notes.push(
      real
        ? `${SAY_SIMULATED[0]?.toUpperCase()}${SAY_SIMULATED.slice(1)} people are hidden: real users only.`
        : `${SAY_SIMULATED[0]?.toUpperCase()}${SAY_SIMULATED.slice(1)} people are hidden, and no area has ${coverage.minPeople} or more real users yet.`,
    );
  }
  return notes;
}
EOF
cat > hooks/useShowSimulated.ts <<'EOF'
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useEffect, useState } from "react";

const KEY = "kip.map.showSimulated";

/**
 * Whether the map shows simulated people. On until turned off, then remembered on this device
 * (AsyncStorage on iOS, localStorage on the web), so a demo phone or dashboard stays as set.
 */
export function useShowSimulated(): [boolean, (show: boolean) => void] {
  const [show, setShow] = useState(true);
  useEffect(() => {
    let live = true;
    AsyncStorage.getItem(KEY)
      .then((saved) => {
        if (live && saved !== null) setShow(saved === "true");
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, []);
  const change = (next: boolean) => {
    setShow(next);
    void AsyncStorage.setItem(KEY, String(next)).catch(() => undefined);
  };
  return [show, change];
}
EOF
